#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

typedef struct {
    int id;
    char username[100];
    char name[100];
    char email[100];
    char phone[20];
    char address[200];
    int is_active;
} Customer;

int fetch_customer_by_username(sqlite3 *db, const char *username, Customer *customer) {
    sqlite3_stmt *stmt;
    const char *sql = "SELECT id, username, name, email, phone, address, is_active FROM customer WHERE username = ?;";
    int rc;

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);

    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        customer->id = sqlite3_column_int(stmt, 0);
        strncpy(customer->username, (const char*)sqlite3_column_text(stmt, 1), sizeof(customer->username) - 1);
        customer->username[sizeof(customer->username) - 1] = '\0';
        strncpy(customer->name, (const char*)sqlite3_column_text(stmt, 2), sizeof(customer->name) - 1);
        customer->name[sizeof(customer->name) - 1] = '\0';
        strncpy(customer->email, (const char*)sqlite3_column_text(stmt, 3), sizeof(customer->email) - 1);
        customer->email[sizeof(customer->email) - 1] = '\0';
        strncpy(customer->phone, (const char*)sqlite3_column_text(stmt, 4), sizeof(customer->phone) - 1);
        customer->phone[sizeof(customer->phone) - 1] = '\0';
        strncpy(customer->address, (const char*)sqlite3_column_text(stmt, 5), sizeof(customer->address) - 1);
        customer->address[sizeof(customer->address) - 1] = '\0';
        customer->is_active = sqlite3_column_int(stmt, 6);
        sqlite3_finalize(stmt);
        return 0;
    } else if (rc == SQLITE_DONE) {
        sqlite3_finalize(stmt);
        return 1; // Not found
    } else {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }
}

void print_customer(const Customer *customer) {
    printf("Customer Information:\n");
    printf("ID: %d\n", customer->id);
    printf("Username: %s\n", customer->username);
    printf("Name: %s\n", customer->name);
    printf("Email: %s\n", customer->email);
    printf("Phone: %s\n", customer->phone);
    printf("Address: %s\n", customer->address);
    printf("Active: %s\n", customer->is_active ? "Yes" : "No");
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <customerusername>\n", argv[0]);
        return 1;
    }

    const char *username = argv[1];
    sqlite3 *db;
    Customer customer;
    int rc;

    rc = sqlite3_open("customers.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    rc = fetch_customer_by_username(db, username, &customer);
    if (rc == 0) {
        print_customer(&customer);
    } else if (rc == 1) {
        printf("Customer with username '%s' not found.\n", username);
    } else {
        sqlite3_close(db);
        return 1;
    }

    sqlite3_close(db);
    return 0;
}
