int fetch_customer_by_username(sqlite3 *db, const char *username, Customer *out) {
    sqlite3_stmt *stmt;
    const char *sql = "SELECT id, username, name, email, phone, address, is_active FROM customer WHERE username = ? LIMIT 1;";
    int rc;

    if (!db || !username || !out) return -1;

    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) return -1;

    sqlite3_bind_text(stmt, 1, username, -1, SQLITE_STATIC);

    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        out->id = sqlite3_column_int(stmt, 0);
        const unsigned char *text;

        text = sqlite3_column_text(stmt, 1);
        strncpy(out->username, text ? (const char*)text : "", sizeof(out->username) - 1);
        out->username[sizeof(out->username) - 1] = '\0';

        text = sqlite3_column_text(stmt, 2);
        strncpy(out->name, text ? (const char*)text : "", sizeof(out->name) - 1);
        out->name[sizeof(out->name) - 1] = '\0';

        text = sqlite3_column_text(stmt, 3);
        strncpy(out->email, text ? (const char*)text : "", sizeof(out->email) - 1);
        out->email[sizeof(out->email) - 1] = '\0';

        text = sqlite3_column_text(stmt, 4);
        strncpy(out->phone, text ? (const char*)text : "", sizeof(out->phone) - 1);
        out->phone[sizeof(out->phone) - 1] = '\0';

        text = sqlite3_column_text(stmt, 5);
        strncpy(out->address, text ? (const char*)text : "", sizeof(out->address) - 1);
        out->address[sizeof(out->address) - 1] = '\0';

        out->is_active = sqlite3_column_int(stmt, 6);

        sqlite3_finalize(stmt);
        return 0;
    } else if (rc == SQLITE_DONE) {
        sqlite3_finalize(stmt);
        return 1;
    } else {
        sqlite3_finalize(stmt);
        return -1;
    }
}

void print_customer_json(const Customer *c) {
